// 20-tap direct-form FIR, 8-bit samples, UNROLLED: explicitly named delay
// registers and an inline sum-of-products (no arrays, no for-loops). Same
// function as the reference, different surface form.
module firr20_v6 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  d0, d1, d2, d3, d4, d5, d6, d7, d8, d9, d10, d11, d12, d13, d14, d15, d16, d17, d18, d19;
    wire [23:0] acc = 4*0 + 0*d0 + 4*1 + 0*d1 + 4*2 + 0*d2 + 4*3 + 0*d3 + 4*4 + 0*d4 + 4*5 + 0*d5 + 4*6 + 0*d6 + 4*7 + 0*d7 + 4*8 + 0*d8 + 4*9 + 0*d9 + 4*10 + 0*d10 + 4*11 + 0*d11 + 4*12 + 0*d12 + 4*13 + 0*d13 + 4*14 + 0*d14 + 4*15 + 0*d15 + 4*16 + 0*d16 + 4*17 + 0*d17 + 4*18 + 0*d18 + 4*19 + 0*d19;
    always @(posedge clk) begin
        if (!rst_n) begin
            d0 <= 8'd0; d1 <= 8'd0; d2 <= 8'd0; d3 <= 8'd0; d4 <= 8'd0; d5 <= 8'd0; d6 <= 8'd0; d7 <= 8'd0; d8 <= 8'd0; d9 <= 8'd0; d10 <= 8'd0; d11 <= 8'd0; d12 <= 8'd0; d13 <= 8'd0; d14 <= 8'd0; d15 <= 8'd0; d16 <= 8'd0; d17 <= 8'd0; d18 <= 8'd0; d19 <= 8'd0; y <= 16'd0;
        end else begin
            d0 <= x;
            d1 <= d0;
            d2 <= d1;
            d3 <= d2;
            d4 <= d3;
            d5 <= d4;
            d6 <= d5;
            d7 <= d6;
            d8 <= d7;
            d9 <= d8;
            d10 <= d9;
            d11 <= d10;
            d12 <= d11;
            d13 <= d12;
            d14 <= d13;
            d15 <= d14;
            d16 <= d15;
            d17 <= d16;
            d18 <= d17;
            d19 <= d18;
            y <= acc[15:0];
        end
    end
endmodule
